INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90000, 'Khái niệm “Tư tưởng Hồ Chí Minh” không bao gồm nội dung nào sau', 'MULTIPLE_CHOICE', 90001, 9999, 'APPROVED');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90000, 'Hệ thống các quan điểm lý luận, phản ánh những vấn đề có tính quy luật của cách mạng Việt Nam.', false, 90000);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90001, 'Nguồn gốc tư tưởng, lý luận của tư tưởng Hồ Chí Minh: chủ nghĩa Mác – Lênin; giá trị văn hoá dân tộc, tinh hoa văn hoá nhân loại.', false, 90000);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90002, 'Nội dung cơ bản nhất của tư tưởng Hồ Chí Minh, bao gồm những vấn đề có liên quan trực tiếp đến cách mạng Việt Nam. Tư tưởng Hồ Chí Minh soi đường thắng lợi cho cách mạng Việt Nam, tài sản tinh thần to lớn của Đảng và dân tộc.', false, 90000);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90003, 'Bao gồm những vấn đề có liên quan đến cách mạng thế giới, tài sản tinh thần cho cách mạng thế giới', true, 90000);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90001, 'Điền vào chỗ trống trong Văn kiện Đại hội lần thứ VI của Đảng Cộng sản Việt Nam (1986): “Muốn đổi mới tư duy, Đảng phải nắm vững bản chất cách mạng và khoa học của chủ nghĩa Mác – Lênin, kế thừa di sản quý báu về ……. của Hồ Chí Minh”:', 'MULTIPLE_CHOICE', 90001, 9999, 'APPROVED');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90004, 'Lý luận và đường lối chính trị.', false, 90001);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90005, 'Tư tưởng và đường lối chính trị.', false, 90001);
