INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90002, 'Khái niệm “Tư tưởng Hồ Chí Minh” lần đầu tiên được Đảng Cộng sản Việt Nam đưa ra tại đại hội lần thứ mấy?', 'MULTIPLE_CHOICE', 90001, 9999, 'APPROVED');
