INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90019, 'Nghiên cứu những đánh giá của các danh nhân trên thế giới về Hồ Chí Minh.', false, 90004);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90005, '“Tư tưởng Hồ Chí Minh là một hệ thống quan điểm toàn diện và sâu sắc về những vấn đề cơ bản của cách mạng Việt Nam”. Những vấn đề cơ bản của cách mạng Việt Nam là:', 'MULTIPLE_CHOICE', 90001, 9999, 'APPROVED');
