INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90023, 'Cả ba phương án kia đều đúng.', true, 90005);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90006, 'Năm 1970, Đảng Cộng sản Việt Nam đưa ra khẩu hiệu tuyên truyền, cổ động về tư tưởng, tấm gương đạo đức Hồ Chí Minh là:', 'MULTIPLE_CHOICE', 90001, 9999, 'APPROVED');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90024, 'Toàn Đảng hãy ra sức học tập đường lối chính trị, tác phong và đạo đức cách mạng của Hồ Chủ tịch.', false, 90006);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90025, 'Toàn Đảng, toàn dân thực hiện cần, kiệm, liêm, chính, chí công, vô tư theo tấm gương của Chủ tịch Hồ Chí Minh vĩ đại.', false, 90006);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90026, 'Sống và làm việc theo gương Bác Hồ vĩ đại.', false, 90006);
