INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90007, 'Tại Đại hội lần thứ VII (1991), Đảng Cộng sản Việt Nam đã khẳng định Tư tưởng Hồ Chí Minh là:', 'MULTIPLE_CHOICE', 90001, 9999, 'APPROVED');
