INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90014, 'Ý nghĩa của việc học tập môn học Tư tưởng Hồ Chí Minh là:', 'MULTIPLE_CHOICE', 90001, 9999, 'APPROVED');
