INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90018, 'Nhận định sau đây của Chủ tịch Hồ Chí Minh trong tác phẩm nào: “Toàn Đảng, toàn dân ta đoàn kết phấn đấu, xây dựng một nước Việt Nam hòa bình, thống nhất, độc lập, dân chủ và giàu mạnh, và góp phần xứng đáng vào sự nghiệp cách mạng thế giới”?', 'MULTIPLE_CHOICE', 90001, 9999, 'APPROVED');
