INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90076, 'Nguyên tắc phân phối theo lao động thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam được Hồ Chí Minh giải thích là:', 'MULTIPLE_CHOICE', 90002, 9999, 'APPROVED');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90303, 'Tất cả mọi người đều phải tích cực lao động, sản phẩm xã hội được chia đều.', false, 90076);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90304, 'Làm theo năng lực, hưởng theo nhu cầu.', false, 90076);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90305, 'Ai làm nhiều thì ăn nhiều, ai làm ít thì ăn ít, ai không làm thì không ăn…', true, 90076);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90306, 'Làm theo năng lực, hưởng theo trách nhiệm được giao.', false, 90076);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90077, 'Trong tác phẩm “Thường thức chính trị”, khi nói về những đặc điểm lớn của chủ nghĩa xã hội, Hồ Chí Minh giải thích nguyên nhân khiến cho trong chủ nghĩa xã hội: “Không có sự đối lập giữa thành thị và thôn quê, giữa lao động chân tay và lao động trí óc” là vì:', 'MULTIPLE_CHOICE', 90002, 9999, 'APPROVED');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90307, 'Vì đô thị hóa rất nhanh, công nghiệp hóa, hiện đại hóa đất nước rất mạnh.', false, 90077);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90308, 'Vì công nhân, nông dân nắm quyền lực chính trị.', false, 90077);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90309, 'Vì thôn quê ngày càng văn minh, công nông ngày càng thông thái.', true, 90077);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90310, 'Vì mọi vùng nông thôn đều trở thành thành thị.', false, 90077);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90078, '“Đồng bào Nam bộ là dân nước Việt Nam. Sông có thể cạn, núi có thể mòn, song chân lý đó không bao giờ thay đổi!”. Câu nói trên của Hồ Chí Minh được trích ra từ văn kiện nào?', 'MULTIPLE_CHOICE', 90002, 9999, 'APPROVED');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90311, 'Thư gửi đồng bào Nam bộ.', true, 90078);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90312, 'Bài nói chuyện cùng đồng bào trước khi sang Pháp.', false, 90078);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90313, 'Lời kêu gọi Kiều bào Việt Nam ở Pháp.', false, 90078);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90314, 'Trả lời phóng viên Hãng thông tấn A.F.P.', false, 90078);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90079, '“Chúng ta cách mệnh thì cũng phải liên lạc tất cả những đảng cách mệnh trong thế giới để chống lại tư bản và đế quốc chủ nghĩa”. Luận điểm đó được Hồ Chí Minh viết trong tác phẩm nào?', 'MULTIPLE_CHOICE', 90002, 9999, 'APPROVED');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90315, 'Sách lược vắn tắt của Đảng.', false, 90079);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90316, 'Chương trình tóm tắt của Đảng.', false, 90079);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90317, 'Đường cách mệnh.', true, 90079);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90318, 'Chánh cương vắn tắt của Đảng.', false, 90079);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90080, 'Chủ trương “làm tư sản dân quyền cách mạng và thổ địa cách mạng để đi tới xã hội cộng sản” được ghi nhận trong văn kiện nào của Hồ Chí Minh?', 'MULTIPLE_CHOICE', 90002, 9999, 'APPROVED');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90319, 'Chánh cương vắn tắt của Đảng.', true, 90080);
