INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90084, 'Điều mong muốn cuối cùng của Hồ Chí Minh được nêu trong Di chúc', 'MULTIPLE_CHOICE', 90002, 9999, 'APPROVED');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90335, 'Xây dựng một nước Việt Nam độc lập, tự do, hạnh phúc.', false, 90084);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90336, 'Xây dựng một nước Việt Nam giàu mạnh, sánh vai với các cường quốc năm châu.', false, 90084);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90337, 'Xây dựng một nước Việt Nam hoà bình, thống nhất, độc lập, dân chủ và giàu mạnh, và góp phần xứng đáng vào sự nghiệp cách mạng thế giới.', true, 90084);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90338, 'Xây dựng một nước Việt Nam dân giàu, nước mạnh, dân chủ, công bằng, văn minh.', false, 90084);
