INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90358, 'Dựa vào sự giúp đỡ của quốc tế.', false, 90089);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90090, 'Theo Hồ Chí Minh, giải phóng dân tộc là nhiệm vụ hàng đầu của cách mạng ở các nước thuộc địa vì:', 'MULTIPLE_CHOICE', 90002, 9999, 'APPROVED');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90359, 'Giải phóng dân tộc là tiền đề để giải phóng giai cấp.', false, 90090);
