INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90103, 'Mục tiêu cụ thể của về kinh tế trong thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam theo tư tưởng Hồ Chí Minh là gì?', 'MULTIPLE_CHOICE', 90002, 9999, 'APPROVED');
