INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90108, 'Theo tư tưởng Hồ Chí Minh, động lực quan trọng và quyết định của của chủ nghĩa xã hội ở Việt Nam là gì?', 'MULTIPLE_CHOICE', 90002, 9999, 'APPROVED');
