INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90441, 'Chủ nghĩa cá nhân.', true, 90110);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90111, 'Quan điểm của Hồ Chí Minh về động lực xây dựng chủ nghĩa xã hội ở Việt Nam là gì?', 'MULTIPLE_CHOICE', 90002, 9999, 'APPROVED');
