INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90113, 'Đặc điểm to nhất khi Việt Nam quá độ lên chủ nghĩa xã hội theo tư tưởng Hồ Chí Minh là:', 'MULTIPLE_CHOICE', 90002, 9999, 'APPROVED');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90450, 'Từ một nước thuộc địa, nửa phong kiến, trình độ pháp luật còn kém', false, 90113);
