INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90114, 'Theo Hồ Chí Minh, động lực quan trọng nhất của cách mạng xã hội chủ nghĩa Việt Nam là:', 'MULTIPLE_CHOICE', 90002, 9999, 'APPROVED');
