INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90120, 'Hồ Chí Minh nói tới văn kiện nào trong câu sau: “Hỡi đồng bào bị đọa đày đau khổ! Đây là cái cần thiết cho chúng ta, đây là con đường giải phóng chúng ta”?', 'MULTIPLE_CHOICE', 90003, 9999, 'APPROVED');
