INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90127, 'Theo Hồ Chí Minh, cách mạng Việt Nam cần phải có Đảng để làm gì?', 'MULTIPLE_CHOICE', 90003, 9999, 'APPROVED');
