INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90129, 'Hồ Chí Minh yêu cầu Đảng phải là đạo đức, là văn minh, mỗi đảng viên và cán bộ phải thật sự thấm nhuần đạo đức cách mạng, thật sự cần kiệm liêm chính, chí công vô tư. Phải giữ gìn Đảng ta thật trong sạch, phải xứng đáng là người lãnh đạo, người đầy tớ thật trung thành của ai?', 'MULTIPLE_CHOICE', 90003, 9999, 'APPROVED');
