INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90170, 'So với học thuyết Mác - Lênin, Hồ Chí Minh đã bổ sung yếu tố nào trong sự thành lập Đảng Cộng sản Việt Nam?', 'MULTIPLE_CHOICE', 90004, 9999, 'APPROVED');
