INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90688, 'Đoàn kết quốc tế.', false, 90172);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90173, 'Theo Hồ Chí Minh, khi lợi ích chung của Đảng mâu thuẫn với lợi ích riêng của cá nhân thì người đảng viên phải như thế nào?', 'MULTIPLE_CHOICE', 90004, 9999, 'APPROVED');
