INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90696, 'Kim Nhật Thành.', false, 90174);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90175, 'Điền vào chỗ trống trong câu nói sau của Hồ Chí Minh: “Đảng có những điều kiện kỷ luật bắt buộc mỗi đảng viên phải theo. Không có kỷ luật sắt không có Đảng. Đã vào Đảng thì phải theo tư tưởng của Đảng. Đảng đã chỉ thị nghị quyết là phải làm. Không làm thì … …”.', 'MULTIPLE_CHOICE', 90004, 9999, 'APPROVED');
