INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90717, 'Tư cách, phẩm chất, năng lực cần thiết.', false, 90180);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90718, 'Phải làm cho dân tin, dân phục để dân theo.', false, 90180);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90719, 'Cả ba phương án kia đều đúng.', true, 90180);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90181, 'Theo Hồ Chí Minh, trong xây dựng Đảng về chính trị, vấn đề nào là “cốt tử”?', 'MULTIPLE_CHOICE', 90004, 9999, 'APPROVED');
