INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90184, 'Trong bài nói chuyện tại lớp Nghiên cứu chính trị khóa I, Trường Đại học Nhân dân Việt Nam (21/7/1956), Hồ Chí Minh cho rằng: “Trong sự nghiệp cách mạng, trong sự nghiệp xây dựng xã hội chủ nghĩa, lao động trí óc có một vai trò quan trọng và vẻ vang; và công, nông, trí, cần phải…..”. Chọn phương án đúng điền vào chỗ trống.', 'MULTIPLE_CHOICE', 90004, 9999, 'APPROVED');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90732, 'Đoàn kết chặt chẽ.', false, 90184);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90733, 'Đoàn kết chặt chẽ thành một khối.', true, 90184);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90734, 'Đoàn kết chặt chẽ và đấu tranh.', false, 90184);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90735, 'Đoàn kết thống nhất thành một khối.', false, 90184);
