INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90189, 'Đánh giá sau đây của ai về vai trò và những cống hiến của Hồ Chí Minh cho cách mạng thế giới: “Bất cứ nơi nào chiến đấu cho độc lập tự do, ở đó có Hồ Chí Minh và ngọn cờ Hồ Chí Minh bay cao. Bất cứ ở đâu chiến đấu cho hòa bình và công lý, ở đó có Hồ Chí Minh và ngọn cờ Hồ Chí Minh bay cao. Ở bất cứ đâu nhân dân chiến đấu cho một thế giới mới, chống lại đói nghèo, ở đó có Hồ Chí Minh và ngọn cờ Hồ Chí Minh bay cao”.', 'MULTIPLE_CHOICE', 90004, 9999, 'APPROVED');
