INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90839, 'Chủ nghĩa quốc tế vô sản.', false, 90210);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90211, 'Câu nói sau của Hồ Chí Minh là về nguyên tắc nào trong tư tưởng đoàn kết quốc tế: “Thực lực là cái chiêng mà ngoại giao là cái tiếng. Chiêng có to, tiếng mới lớn”?', 'MULTIPLE_CHOICE', 90004, 9999, 'APPROVED');
