INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90213, 'Theo Hồ Chí Minh, bản chất của các đoàn thể, tổ chức quần chúng nhân dân là:', 'MULTIPLE_CHOICE', 90004, 9999, 'APPROVED');
