INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90851, 'Tổ chức của Quốc tế cộng sản.', false, 90213);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90214, 'Nền văn hóa mới mà chúng ta xây dựng theo tư tưởng Hồ Chí Minh bao gồm tính dân tộc, tính đại chúng và tính chất gì?', 'MULTIPLE_CHOICE', 90004, 9999, 'APPROVED');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (90852, 'Hiện đại.', false, 90214);
