INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90229, 'Bản chất của tư tưởng đạo đức Hồ Chí Minh là gì?', 'MULTIPLE_CHOICE', 90005, 9999, 'APPROVED');
