INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90231, 'Quan điểm của Hồ Chí Minh về vị trí và vai trò của văn hóa trong đời sống xã hội: “Xã hội thế nào, văn hóa thế ấy. Văn nghệ của dân tộc ta vốn rất phong phú, nhưng dưới chế độ thực dân và phong kiến nhân dân ta bị nô lệ thì văn nghệ cũng bị nô lệ, bị tồi tàn không thể phát triển được”, “Rõ ràng là dân tộc bị áp bức thì văn nghệ cũng mất tự do. Văn nghệ muốn tự do thì phải ….. ”. Chọn phương án đúng điền vào chỗ trống.', 'MULTIPLE_CHOICE', 90005, 9999, 'APPROVED');
