INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90255, 'Điền vào chỗ trống trong câu sau của Hồ Chí Minh: “Hiểu chủ nghĩa Mác - Lênin là….. Nếu thuộc bao nhiêu sách mà sống không có tình có nghĩa thì sao gọi là hiểu chủ nghĩa Mác - Lênin được” ?', 'MULTIPLE_CHOICE', 90005, 9999, 'APPROVED');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91016, 'Phải hiểu những nguyên lý.', false, 90255);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91017, 'Phải các cặp phạm trù, quy luật.', false, 90255);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91018, 'Phải sống với nhau có tình, có nghĩa.', true, 90255);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91019, 'Phải làm việc tốt.', false, 90255);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90256, 'Theo Hồ Chí Minh đạo đức cách mạng là một phạm trù lịch sử, nghĩa là nó cũng thay đổi theo nhiệm vụ từng thời kỳ của cách mạng, “đạo đức xã hội chủ nghĩa không phải ở đâu cũng biểu hiện giống nhau. Ở nước ta đạo đức xã hội chủ nghĩa là …..”. Chọn phương án đúng điền vào chỗ trống.', 'MULTIPLE_CHOICE', 90005, 9999, 'APPROVED');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91020, 'Lao động xây dựng nước nhà.', false, 90256);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91021, 'Cần kiệm xây dựng nước nhà.', true, 90256);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91022, 'Bảo vệ tổ quốc xã hội chủ nghĩa.', false, 90256);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91023, 'Học tập, lao động, nghiên cứu khoa học.', false, 90256);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90257, 'Hồ Chí Minh yêu cầu Đảng phải “là đạo đức, là văn minh”; “Mỗi đảng viên và cán bộ phải thật sự thấm nhuần đạo đức cách mạng, thật sự cần kiệm liêm chính, chí công vô tư. Phải giữ gìn Đảng ta thật trong sạch, phải xứng đáng là người lãnh đạo, ….. ”. Chọn phương án đúng điền vào chỗ trống.', 'MULTIPLE_CHOICE', 90005, 9999, 'APPROVED');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91024, 'Là người chỉ đường cho nhân dân.', false, 90257);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91025, 'Là người chỉ huy tài tình cho cách mạng.', false, 90257);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91026, 'Là người đầy tớ thật trung thành của nhân dân.', true, 90257);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91027, 'Là người dẫn dắt nhân dân đến thắng lợi cuối cùng.', false, 90257);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90258, 'Nhận định sau đây là của ai: “Chủ tịch Hồ Chí Minh, một biểu tượng xuất sắc về sự tự khẳng định dân tộc, đã cống hiến trọn đời mình cho sự nghiệp giải phóng dân tộc của nhân dân Việt Nam, góp phần vào cuộc đấu tranh chung của các dân tộc vì hòa bình, độc lập dân tộc, dân chủ và tiến bộ xã hội”?', 'MULTIPLE_CHOICE', 90005, 9999, 'APPROVED');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91028, 'M.I. Matsna (Apganixtan).', false, 90258);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91029, 'Tổng thống Xu-các-nô (Indonesia).', false, 90258);
