INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91031, 'Tổ chức Giáo dục, Khoa học và Văn hóa Liên hợp quốc (UNESCO).', true, 90258);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90259, 'Chọn phương án đúng điền vào chỗ trống trong câu sau của Hồ Chí Minh: “Người cách mạng phải có ….. thì mới gánh được nặng và đi được xa”?', 'MULTIPLE_CHOICE', 90005, 9999, 'APPROVED');
