INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91044, 'Có ý thức làm chủ, tinh thần tập thể xã hội chủ nghĩa và tư tưởng “mình vì mọi người, mọi người vì mình”.', false, 90262);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91045, 'Cần kiệm xây dựng đất nước, hăng hái bảo vệ Tổ quốc; Có lòng yêu nước nồng nàn, tinh thần quốc tế trong sáng.', false, 90262);
