INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90265, 'Hồ Chí Minh đã chỉ rõ: Phải làm thế nào cho văn hóa thấm sâu vào tâm lý quốc dân, nghĩa là văn hóa phải sửa đổi được những tham nhũng, lười biếng, phù hoa, xa xỉ; văn hóa phải ….. Chọn phương án đúng điền vào chỗ trống.', 'MULTIPLE_CHOICE', 90005, 9999, 'APPROVED');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91056, 'Xây dựng tình cảm cao đẹp.', false, 90265);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91057, 'Bồi dưỡng tư tưởng đúng đắn.', false, 90265);
