INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91059, 'Soi đường cho quốc dân đi.', true, 90265);
INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90266, 'Hồ Chí Minh coi trọng văn hóa, học vấn, trí tuệ. Người nói: “Muốn xây dựng chủ nghĩa xã hội thì nhất định phải có ….. Cần phải học văn hóa, chính trị, kỹ thuật”. “Người có học mới có tiến bộ, càng học càng tiến bộ”. Chọn phương án đúng điền vào chỗ trống.', 'MULTIPLE_CHOICE', 90005, 9999, 'APPROVED');
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91060, 'Học thức.', true, 90266);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91061, 'Giáo dục.', false, 90266);
INSERT INTO _answer (id, text, is_correct, question_id) VALUES (91062, 'Khoa học.', false, 90266);
