INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90268, 'Chọn phương án đúng vào chỗ trống trong câu sau của Hồ Chí Minh: “Người đi giáo dục ….. phải học thêm mãi, học không bao giờ đủ, còn sống còn phải học”.', 'MULTIPLE_CHOICE', 90005, 9999, 'APPROVED');
