INSERT INTO _question (id, text, type, category_id, created_id, approval_status) VALUES (90269, 'Hồ Chí Minh nói về vai trò của “làm gương” trong thực hiện đời sống mới: “Đời sống mới cũng cần có ….. Khi trông thấy những kết quả tốt tươi, thì chắc những nơi khác sẽ hăng hái làm theo”. Chọn phương án đúng điền vào chỗ trống.', 'MULTIPLE_CHOICE', 90005, 9999, 'APPROVED');
